<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { Download, RefreshCw } from '@lucide/vue'
import { apiError, learningApi, type EvaluationSummary } from '../api/client'
import SectionHeading from '../components/SectionHeading.vue'

const rows = ref<EvaluationSummary[]>([]), condition = ref(''), loading = ref(true), error = ref('')
async function load() { loading.value = true; error.value = ''; try { rows.value = await learningApi.evaluationSummary(condition.value || undefined) } catch (cause) { error.value = apiError(cause, '评估汇总暂时无法读取') } finally { loading.value = false } }
async function download() { try { const blob = await learningApi.exportEvaluationSummary(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'learning-evaluation-anonymized.csv'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) } catch (cause) { error.value = apiError(cause, '去标识化导出失败') } }
onMounted(() => void load())
</script>

<template>
  <div class="page-stack evaluation-admin-page"><SectionHeading eyebrow="管理后台 · 研究数据" title="去标识化学习评估汇总" description="按条件展示样本量、均值、中位数、标准差和四分位距；导出文件仅包含匿名参与者编号、分组、顺序、用时、Paas、测验和延后测验字段。"><button class="button button-outline" :disabled="loading" @click="load"><RefreshCw :size="15" />刷新</button><button class="button button-dark" :disabled="loading" @click="download"><Download :size="15" />导出匿名 CSV</button></SectionHeading><div v-if="error" class="inline-notice" role="alert">{{ error }}</div><section class="content-section evaluation-admin-note"><strong>学术边界</strong><span>系统不采集生理信号，不把单次 Paas 评分解释为已降低认知负荷；自动统计用于后续外部统计检验。</span></section><section class="content-section"><div class="evaluation-admin-filter"><label>条件筛选<select v-model="condition" @change="load"><option value="">全部条件</option><option value="METHODS">问答方法对照</option><option value="QWEN_MATRIX">Qwen基座与LoRA对照</option><option value="LEARNING_TASK">课程学习任务</option></select></label></div><div v-if="loading" class="empty-state"><span class="spinner"></span><strong>正在读取汇总</strong></div><div v-else-if="rows.length" class="evaluation-table"><div class="evaluation-row evaluation-head"><strong>条件</strong><strong>n</strong><strong>前测均值/中位数</strong><strong>后测均值/中位数</strong><strong>延后测验</strong><strong>Paas 均值/中位数</strong><strong>用时均值/中位数</strong><strong>反馈数</strong></div><div v-for="row in rows" :key="row.conditionKey" class="evaluation-row"><span>{{ row.conditionKey }}</span><span>{{ row.sampleCount }}</span><span>{{ row.meanPreScore ?? '—' }} / {{ row.medianPreScore ?? '—' }}<small>SD {{ row.stddevPreScore ?? '—' }} · IQR {{ row.iqrPreScore ?? '—' }}</small></span><span>{{ row.meanPostScore ?? '—' }} / {{ row.medianPostScore ?? '—' }}<small>SD {{ row.stddevPostScore ?? '—' }} · IQR {{ row.iqrPostScore ?? '—' }}</small></span><span>{{ row.meanDelayedScore ?? '—' }}<small>中位 {{ row.medianDelayedScore ?? '—' }} · IQR {{ row.iqrDelayedScore ?? '—' }}</small></span><span>{{ row.meanEffort ?? '—' }} / {{ row.medianEffort ?? '—' }}<small>SD {{ row.stddevEffort ?? '—' }} · IQR {{ row.iqrEffort ?? '—' }}</small></span><span>{{ row.meanElapsedSeconds ?? '—' }} / {{ row.medianElapsedSeconds ?? '—' }} 秒<small>SD {{ row.stddevElapsedSeconds ?? '—' }} · IQR {{ row.iqrElapsedSeconds ?? '—' }}</small></span><span>{{ row.feedbackCount }}</span></div></div><div v-else class="empty-state"><strong>暂无已完成评估</strong><span>完成评估会进入匿名聚合汇总。</span></div></section></div>
</template>

<style scoped>
.evaluation-admin-note{display:flex;gap:10px;align-items:baseline;color:var(--text-muted);font-size:11px;line-height:1.6}.evaluation-admin-note strong{color:var(--accent)}.evaluation-admin-filter{display:flex;justify-content:flex-end;margin-bottom:15px}.evaluation-admin-filter label{display:grid;gap:6px;color:var(--text-muted);font-size:11px}.evaluation-admin-filter select{min-width:180px;padding:8px;border:1px solid var(--border-default);border-radius:var(--radius-sm);background:var(--surface)}.evaluation-table{overflow:auto}.evaluation-row{display:grid;grid-template-columns:1.1fr .45fr 1.3fr 1.3fr 1.2fr 1.3fr 1.3fr .6fr;gap:10px;min-width:1120px;padding:13px 0;border-bottom:1px solid var(--border-soft);color:var(--text-muted);font-size:10px}.evaluation-head{color:var(--text);font-size:10px;font-weight:700}.evaluation-row span:first-child{color:var(--text);font-weight:650}.evaluation-row small{display:block;margin-top:4px;color:var(--text-subtle);font-size:9px;line-height:1.45}
</style>
